/***
 * Setup @dynatrace-sdk/error-handlers testing environment with default values
 */
export declare const clearErrorHandlersMocks: () => void;

/**
 * Common serialized JS Error
 */
declare interface CommonSerializedError {
    name: string;
    message: string;
    stack?: string;
    type: ErrorType.COMMON;
    errorRef?: string;
    cause?: any;
    details?: any;
}

/**
 * Possible serialized error types
 * `COMMON`: Common JS error
 * `HTTP`: Error thrown by a http-client
 */
declare enum ErrorType {
    COMMON = "JS Error",
    HTTP = "Http Error"
}

/**
 * Custom error serializing function.
 * Should check the received error and, when the error matches, return a serialized error with the specified error type.
 * Otherwise, nothing should be returned so that the error can be handled further.
 *
 * @param {any} error Error to be serialized
 * @returns {TypedError | undefined} Serialized error or nothing
 */
declare type GlobalErrorSerializer = (error: any) => Promise<SerializedError | undefined>;

/**
 * Serialized http exception with response status
 */
declare interface HttpSerializedError {
    name: string;
    message: string;
    stack?: string;
    type: ErrorType.HTTP;
    status: number;
    /** @deprecated */
    body?: unknown;
    errorRef?: string;
    cause?: any;
    details?: any;
}

/***
 * Setup @dynatrace-sdk/error-handlers for testing purposes
 * The @dynatrace-sdk/error-handlers implementation will be overridden with passed mocked values or defaults mocks
 * @param setup - configuration with mocked values / function
 */
export declare const mockErrorHandlers: (setup?: MockType) => void;

declare type MockType = Partial<typeof wrapper>;

/**
 * Serialized error object contains error type
 *
 * @property {ErrorType} type error type
 */
declare type SerializedError = (HttpSerializedError | CommonSerializedError) & {
    traceId?: string;
};

export declare const setupTestingEnv: () => void;

declare const wrapper: {
    addGlobalErrorSerializer: (serializer: GlobalErrorSerializer) => void;
};

export { }
